-- Create custom types (enums)
CREATE TYPE public.roles AS ENUM ('manager', 'employee', 'owner');
CREATE TYPE public.days AS ENUM ('monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday');
CREATE TYPE public.permissions AS ENUM ('superadmin', 'admin', 'user');
CREATE TYPE public.timezones AS ENUM ('UTC', 'Europe/Paris', 'America/New_York');

-- Create tables
CREATE TABLE IF NOT EXISTS public."planning" (
  "id" BIGSERIAL PRIMARY KEY,
  "is_default" BOOLEAN,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public."team" (
  "id" BIGSERIAL PRIMARY KEY,
  "name" VARCHAR(255),
  "description" VARCHAR(255),
  "lateness_limit" SMALLINT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at" TIMESTAMP,
  "default_planning_id" BIGINT,
  "timezone" VARCHAR(50) NOT NULL DEFAULT 'UTC'
);

CREATE TABLE IF NOT EXISTS public."user" (
  "id" BIGSERIAL PRIMARY KEY,
  "email" VARCHAR(255),
  "password" VARCHAR(255),
  "first_name" VARCHAR(255),
  "last_name" VARCHAR(255),
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "updated_at" TIMESTAMPTZ,
  "permission" VARCHAR(50),
  "phone_number" BIGINT
);

CREATE TABLE IF NOT EXISTS public."user_team" (
  "id" BIGSERIAL PRIMARY KEY,
  "user_id" BIGINT,
  "team_id" BIGINT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  "role" VARCHAR(50),
  "planning_id" BIGINT
);

CREATE TABLE IF NOT EXISTS public."schedule" (
  "id" BIGSERIAL PRIMARY KEY,
  "planning_id" BIGINT,
  "day" VARCHAR(50),
  "time_in" TIME,
  "time_out" TIME,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public."clock" (
  "id" BIGSERIAL PRIMARY KEY,
  "arrival_time" TIMESTAMP,
  "departure_time" TIMESTAMP,
  "user_team_id" BIGINT,
  "planning_id" BIGINT
);

